/** The page's own date, or `fallback` (an ISO string) when it has none. */
export function urlLastmod(path: string, fallback: string | null): string | null {
  const d = URL_DATES[path === '' ? '/' : path];
  return d ? `${d}T00:00:00.000Z` : fallback;
}
